CREATE OR REPLACE FUNCTION private.crm_admin(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND private.has_tenant_role_in(t,ARRAY['owner','admin','platform_admin']::public.app_role[]) $$;
CREATE OR REPLACE FUNCTION private.crm_head_of(t uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND private.is_tenant_member(t) AND EXISTS(SELECT 1 FROM public.team_members h JOIN public.team_members m ON m.team_id=h.team_id AND m.tenant_id=h.tenant_id JOIN public.teams d ON d.id=h.team_id AND d.tenant_id=t AND d.deleted_at IS NULL WHERE h.tenant_id=t AND h.user_id=auth.uid() AND h.is_lead AND m.user_id=u) $$;
CREATE OR REPLACE FUNCTION private.crm_read(t uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (private.has_tenant_role_in(t,ARRAY['owner','admin','platform_admin','manager']::public.app_role[]) OR (private.has_tenant_role_in(t,ARRAY['agent']::public.app_role[]) AND u=auth.uid()) OR private.crm_head_of(t,u)) $$;
CREATE OR REPLACE FUNCTION private.crm_write(t uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.crm_admin(t) OR (private.has_tenant_role_in(t,ARRAY['agent']::public.app_role[]) AND u=auth.uid()) $$;
CREATE OR REPLACE FUNCTION private.crm_record_read(t uuid,kind text,rid uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE own uuid; BEGIN IF rid IS NULL THEN RETURN false; END IF; IF kind='lead' THEN SELECT owner_user_id INTO own FROM public.leads WHERE id=rid AND tenant_id=t; ELSIF kind='customer' THEN SELECT owner_user_id INTO own FROM public.customers WHERE id=rid AND tenant_id=t; ELSIF kind='contract' THEN SELECT owner_user_id INTO own FROM public.contracts WHERE id=rid AND tenant_id=t; ELSIF kind='conversation' THEN SELECT owner_user_id INTO own FROM public.conversations WHERE id=rid AND tenant_id=t; ELSIF kind='deal' THEN SELECT owner_user_id INTO own FROM public.pipeline_deals WHERE id=rid AND tenant_id=t; ELSE RETURN false; END IF; IF NOT FOUND THEN RETURN false; END IF; RETURN private.crm_read(t,own); END $$;
REVOKE ALL ON FUNCTION private.crm_admin(uuid),private.crm_head_of(uuid,uuid),private.crm_read(uuid,uuid),private.crm_write(uuid,uuid),private.crm_record_read(uuid,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.crm_admin(uuid),private.crm_head_of(uuid,uuid),private.crm_read(uuid,uuid),private.crm_write(uuid,uuid),private.crm_record_read(uuid,text,uuid) TO authenticated,service_role;
DO $$ DECLARE t text;p record;rd text;wr text; BEGIN
FOREACH t IN ARRAY ARRAY['leads','customers','pipeline_deals','ai_followups','contracts','conversations','appointments','call_logs','conversation_messages','contract_installments','contract_commissions','customer_transactions','ai_lead_scores','files','message_tickets','lead_submissions','nurture_messages','payment_reminders'] LOOP
FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,t); END LOOP;
IF t IN ('leads','customers','pipeline_deals','ai_followups') THEN rd:='private.crm_read(tenant_id,owner_user_id)';wr:='private.crm_write(tenant_id,owner_user_id)';
ELSIF t='contracts' THEN rd:='private.crm_read(tenant_id,owner_user_id)';wr:='private.crm_admin(tenant_id)';
ELSIF t='conversations' THEN rd:='private.crm_admin(tenant_id) OR (private.has_tenant_role_in(tenant_id,ARRAY[''agent'']::public.app_role[]) AND (owner_user_id=auth.uid() OR owner_user_id IS NULL))';wr:=rd;
ELSIF t='appointments' THEN rd:='private.crm_read(tenant_id,assigned_to)';wr:='private.crm_write(tenant_id,assigned_to)';
ELSIF t='call_logs' THEN rd:='private.crm_read(tenant_id,agent_user_id)';wr:='private.crm_write(tenant_id,agent_user_id)';
ELSIF t='conversation_messages' THEN rd:='private.crm_record_read(tenant_id,''conversation'',conversation_id)';wr:='private.crm_admin(tenant_id) OR (private.has_tenant_role_in(tenant_id,ARRAY[''agent'']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_messages.conversation_id AND c.tenant_id=conversation_messages.tenant_id AND c.owner_user_id=auth.uid()))';
ELSIF t IN ('contract_installments','contract_commissions','payment_reminders') THEN rd:='private.crm_record_read(tenant_id,''contract'',contract_id)';wr:='private.crm_admin(tenant_id)';
ELSIF t='customer_transactions' THEN rd:='private.crm_record_read(tenant_id,''customer'',customer_id)';wr:='private.crm_admin(tenant_id)';
ELSIF t IN ('ai_lead_scores','nurture_messages') THEN rd:='private.crm_record_read(tenant_id,''lead'',lead_id)';wr:='private.crm_admin(tenant_id)';
ELSIF t='lead_submissions' THEN rd:='private.crm_record_read(tenant_id,''lead'',created_lead_id)';wr:='private.crm_admin(tenant_id)';
ELSIF t='message_tickets' THEN rd:='private.crm_record_read(tenant_id,''conversation'',conversation_id)';wr:='private.crm_admin(tenant_id) OR (private.has_tenant_role_in(tenant_id,ARRAY[''agent'']::public.app_role[]) AND private.crm_record_read(tenant_id,''conversation'',conversation_id))';
ELSIF t='files' THEN rd:='private.crm_admin(tenant_id) OR (private.is_tenant_member(tenant_id) AND ((related_id IS NOT NULL AND private.crm_record_read(tenant_id,related_type,related_id)) OR (related_id IS NULL AND uploaded_by=auth.uid())))';wr:='private.crm_admin(tenant_id) OR (private.has_tenant_role_in(tenant_id,ARRAY[''agent'']::public.app_role[]) AND uploaded_by=auth.uid() AND (related_id IS NULL OR private.crm_record_read(tenant_id,related_type,related_id)))';END IF;
EXECUTE format('CREATE POLICY crm_read ON public.%I FOR SELECT TO authenticated USING (%s)',t,rd);
IF t NOT IN ('payment_reminders','nurture_messages') THEN EXECUTE format('CREATE POLICY crm_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (%s)',t,wr);
IF t IN ('leads','customers','pipeline_deals','appointments') THEN wr:=wr||' OR private.has_tenant_role_in(tenant_id,ARRAY[''manager'']::public.app_role[]) OR private.crm_head_of(tenant_id,'||CASE WHEN t='appointments' THEN 'assigned_to' ELSE 'owner_user_id' END||')';END IF;
EXECUTE format('CREATE POLICY crm_update ON public.%I FOR UPDATE TO authenticated USING (%s) WITH CHECK (%s)',t,wr,wr);
EXECUTE format('CREATE POLICY crm_delete ON public.%I FOR DELETE TO authenticated USING (private.crm_admin(tenant_id))',t);END IF;END LOOP;END $$;
CREATE OR REPLACE FUNCTION public.guard_crm_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n jsonb:=to_jsonb(NEW);o jsonb;own uuid;dest uuid;t uuid:=NEW.tenant_id;col text;admin boolean;
BEGIN IF auth.uid() IS NULL OR current_setting('app.crm_ingest',true)='checked' THEN RETURN NEW;END IF;
col:=CASE WHEN TG_TABLE_NAME='appointments' THEN 'assigned_to' ELSE 'owner_user_id' END;dest:=nullif(n->>col,'')::uuid;admin:=private.crm_admin(t);
IF dest IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE tenant_id=t AND user_id=dest AND role IN ('owner','admin','platform_admin','manager','agent')) THEN RAISE EXCEPTION 'Sale phụ trách không thuộc sàn';END IF;
IF TG_OP='INSERT' THEN IF NOT admin AND dest IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Chỉ được tạo dữ liệu phụ trách của mình';END IF;RETURN NEW;END IF;
o:=to_jsonb(OLD);own:=nullif(o->>col,'')::uuid;IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN RAISE EXCEPTION 'Không được chuyển dữ liệu sang sàn khác';END IF;IF admin THEN RETURN NEW;END IF;
IF TG_TABLE_NAME='conversations' THEN IF n->'lead_id' IS DISTINCT FROM o->'lead_id' AND current_setting('app.crm_profile_link',true) IS DISTINCT FROM 'checked' THEN RAISE EXCEPTION 'Phải ghép hồ sơ qua thao tác đã kiểm tra';END IF;IF dest IS DISTINCT FROM own AND NOT (own IS NULL AND dest=auth.uid() OR own=auth.uid() AND dest IS NULL) THEN RAISE EXCEPTION 'Không được nhận hội thoại của Sale khác';END IF;RETURN NEW;END IF;
IF NOT private.crm_write(t,own) AND (n-ARRAY[col,'team_id','updated_at','sla_due_at','sla_minutes','first_response_at']) IS DISTINCT FROM (o-ARRAY[col,'team_id','updated_at','sla_due_at','sla_minutes','first_response_at']) THEN RAISE EXCEPTION 'Quản lý chỉ được điều phối khách';END IF;
IF dest IS DISTINCT FROM own OR n->'team_id' IS DISTINCT FROM o->'team_id' THEN IF private.has_tenant_role_in(t,ARRAY['manager']::public.app_role[]) THEN RETURN NEW;END IF;
IF NOT private.crm_head_of(t,own) OR NOT EXISTS(SELECT 1 FROM public.team_members h JOIN public.team_members a ON a.team_id=h.team_id AND a.tenant_id=t JOIN public.team_members b ON b.team_id=h.team_id AND b.tenant_id=t WHERE h.tenant_id=t AND h.user_id=auth.uid() AND h.is_lead AND a.user_id=own AND b.user_id=dest AND (n->>'team_id' IS NULL OR b.team_id=(n->>'team_id')::uuid)) THEN RAISE EXCEPTION 'Chỉ được bàn giao trong phòng phụ trách';END IF;END IF;RETURN NEW;END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['leads','customers','pipeline_deals','appointments','conversations'] LOOP EXECUTE format('CREATE TRIGGER z_guard_crm_assignment BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_crm_assignment()',t);END LOOP;END $$;
CREATE OR REPLACE FUNCTION public.guard_crm_tenant_refs() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j jsonb:=to_jsonb(NEW);col text;target text;rid uuid;ok boolean;t uuid:=NEW.tenant_id;
BEGIN IF TG_OP='UPDATE' AND NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN RAISE EXCEPTION 'Không được đổi sàn của dữ liệu';END IF;
FOR col,target IN SELECT * FROM (VALUES ('lead_id','leads'),('customer_id','customers'),('contract_id','contracts'),('conversation_id','conversations'),('deal_id','pipeline_deals'),('product_id','products'),('project_id','projects'),('team_id','teams')) x(c,t) LOOP rid:=nullif(j->>col,'')::uuid;IF rid IS NOT NULL THEN EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE id=$1 AND tenant_id=$2)',target) INTO ok USING rid,t;IF NOT ok THEN RAISE EXCEPTION 'Hồ sơ liên kết không thuộc sàn';END IF;END IF;END LOOP;RETURN NEW;END $$;
DO $$ DECLARE r record;BEGIN FOR r IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='tenant_id' AND table_name IN ('contracts','products','leads','customers','pipeline_deals','conversations','conversation_messages','call_logs','appointments','contract_installments','contract_commissions','customer_transactions','ai_followups','ai_lead_scores','lead_submissions','message_tickets','collaborator_referrals','team_members') LOOP EXECUTE format('CREATE TRIGGER a_guard_crm_tenant_refs BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_crm_tenant_refs()',r.table_name);END LOOP;END $$;
DO $$ DECLARE p record;d text;BEGIN FOR p IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('sync_lead_from_contract','sync_lead_from_product','sync_product_from_contract') LOOP d:=pg_get_functiondef(p.oid);d:=replace(d,'WHERE id = NEW.lead_id AND status','WHERE id = NEW.lead_id AND tenant_id = NEW.tenant_id AND status');d:=replace(d,'WHERE id = NEW.deal_id AND status','WHERE id = NEW.deal_id AND tenant_id = NEW.tenant_id AND status');d:=replace(d,'WHERE id = NEW.deal_id;','WHERE id = NEW.deal_id AND tenant_id = NEW.tenant_id;');d:=replace(d,'WHERE id = _lead AND status','WHERE id = _lead AND tenant_id = NEW.tenant_id AND status');d:=replace(d,'WHERE id = NEW.product_id','WHERE id = NEW.product_id AND tenant_id = NEW.tenant_id');EXECUTE d;END LOOP;END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='create_rental_contract';d:=replace(d,'IF NOT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.tenant_id = p_tenant AND ur.user_id = auth.uid()) THEN','IF NOT private.crm_admin(p_tenant) THEN');EXECUTE d;END $$;
REVOKE EXECUTE ON FUNCTION public.create_rental_contract(uuid,uuid,uuid,uuid,uuid,text,numeric,numeric,date,date,integer,text,jsonb) FROM PUBLIC,anon;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='link_channel_profile';d:=replace(d,'UPDATE public.conversations SET','PERFORM set_config(''app.crm_profile_link'',''checked'',true); UPDATE public.conversations SET');EXECUTE d;END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='collaborator_portal_submit';d:=replace(d,'INSERT INTO public.leads(', 'PERFORM set_config(''app.crm_ingest'',''checked'',true); INSERT INTO public.leads(');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.guard_role_boundary() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RETURN NEW;END IF;IF NEW.role='platform_admin' AND NOT private.is_platform_admin() THEN RAISE EXCEPTION 'Không được cấp quyền quản trị nền tảng';END IF;IF TG_OP='UPDATE' AND (NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN RAISE EXCEPTION 'Không được di chuyển quyền giữa tài khoản hoặc sàn';END IF;RETURN NEW;END $$;
CREATE TRIGGER guard_role_boundary BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_role_boundary();
DO $$ DECLARE p record;BEGIN FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='settings' AND cmd IN ('INSERT','UPDATE','DELETE') LOOP EXECUTE format('DROP POLICY %I ON public.settings',p.policyname);END LOOP;END $$;
CREATE POLICY settings_secure_insert ON public.settings FOR INSERT TO authenticated WITH CHECK(private.crm_admin(tenant_id) OR (key='lead_routing' AND private.has_tenant_role_in(tenant_id,ARRAY['manager']::public.app_role[])));
CREATE POLICY settings_secure_update ON public.settings FOR UPDATE TO authenticated USING(private.crm_admin(tenant_id) OR (key='lead_routing' AND private.has_tenant_role_in(tenant_id,ARRAY['manager']::public.app_role[]))) WITH CHECK(private.crm_admin(tenant_id) OR (key='lead_routing' AND private.has_tenant_role_in(tenant_id,ARRAY['manager']::public.app_role[])));
CREATE POLICY settings_secure_delete ON public.settings FOR DELETE TO authenticated USING(private.crm_admin(tenant_id));
CREATE OR REPLACE FUNCTION public.collaborator_portal_accept(p_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.collaborator_portal_invites;c public.sales_collaborators;verified_email text;
BEGIN IF auth.uid() IS NULL OR p_token IS NULL OR p_token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Lời mời không hợp lệ';END IF;SELECT lower(trim(email)) INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL;IF verified_email IS NULL OR verified_email<>lower(trim(coalesce(auth.jwt()->>'email',''))) THEN RAISE EXCEPTION 'Cần xác nhận email trước khi nhận lời mời';END IF;
SELECT * INTO i FROM public.collaborator_portal_invites WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex') FOR UPDATE;IF NOT FOUND OR i.used_at IS NOT NULL OR i.expires_at<=now() OR verified_email<>i.email THEN RAISE EXCEPTION 'Lời mời hết hạn, đã dùng hoặc không đúng email';END IF;
SELECT * INTO c FROM public.sales_collaborators WHERE id=i.collaborator_id AND tenant_id=i.tenant_id FOR UPDATE;IF NOT FOUND OR c.status<>'active' OR c.portal_user_id IS NOT NULL OR lower(trim(coalesce(c.email,'')))<>i.email THEN RAISE EXCEPTION 'CTV chưa được phép liên kết';END IF;
UPDATE public.sales_collaborators SET portal_user_id=auth.uid(),updated_at=now() WHERE id=c.id;UPDATE public.collaborator_portal_invites SET used_at=now() WHERE id=i.id;INSERT INTO public.audit_logs(tenant_id,actor_user_id,action,entity,entity_id) VALUES(i.tenant_id,auth.uid(),'collaborator.portal_accept','collaborator',c.id);RETURN c.id;END $$;
CREATE OR REPLACE FUNCTION public.expire_changed_ctv_invites() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(trim(coalesce(NEW.email,''))) IS DISTINCT FROM lower(trim(coalesce(OLD.email,''))) OR NEW.status IS DISTINCT FROM OLD.status THEN UPDATE public.collaborator_portal_invites SET expires_at=least(expires_at,now()) WHERE collaborator_id=NEW.id AND tenant_id=NEW.tenant_id AND used_at IS NULL;END IF;RETURN NEW;END $$;
CREATE TRIGGER expire_changed_ctv_invites AFTER UPDATE ON public.sales_collaborators FOR EACH ROW EXECUTE FUNCTION public.expire_changed_ctv_invites();
CREATE OR REPLACE FUNCTION public.accept_crm_invitation(p_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.invitations;email_verified text;
BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Cần đăng nhập';END IF;SELECT lower(trim(email)) INTO email_verified FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL;IF email_verified IS NULL OR email_verified<>lower(trim(coalesce(auth.jwt()->>'email',''))) THEN RAISE EXCEPTION 'Cần xác nhận email';END IF;
SELECT * INTO i FROM public.invitations WHERE token=p_token FOR UPDATE;IF NOT FOUND OR i.status<>'pending' OR i.expires_at<=now() OR lower(trim(i.email))<>email_verified OR i.role='platform_admin' THEN RAISE EXCEPTION 'Lời mời không hợp lệ hoặc không đúng email';END IF;
INSERT INTO public.user_roles(tenant_id,user_id,role) VALUES(i.tenant_id,auth.uid(),i.role) ON CONFLICT(tenant_id,user_id,role) DO NOTHING;UPDATE public.invitations SET status='accepted',accepted_at=now(),accepted_by=auth.uid() WHERE id=i.id;INSERT INTO public.audit_logs(tenant_id,actor_user_id,action,entity,entity_id) VALUES(i.tenant_id,auth.uid(),'invitation.accept','invitation',i.id);RETURN i.tenant_id;END $$;
REVOKE ALL ON FUNCTION public.accept_crm_invitation(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.accept_crm_invitation(text) TO authenticated;
CREATE POLICY crm_private_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='crm-private' AND private.has_tenant_role_in(((storage.foldername(name))[1])::uuid,ARRAY['owner','admin','platform_admin','agent']::public.app_role[]) AND ((storage.foldername(name))[2])=auth.uid()::text);
CREATE POLICY crm_private_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='crm-private' AND (private.crm_admin(((storage.foldername(name))[1])::uuid) OR (private.is_tenant_member(((storage.foldername(name))[1])::uuid) AND ((storage.foldername(name))[2])=auth.uid()::text) OR EXISTS(SELECT 1 FROM public.files f WHERE f.bucket=bucket_id AND f.path=name AND f.deleted_at IS NULL)));
CREATE POLICY crm_private_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='crm-private' AND (private.crm_admin(((storage.foldername(name))[1])::uuid) OR (private.has_tenant_role_in(((storage.foldername(name))[1])::uuid,ARRAY['agent']::public.app_role[]) AND ((storage.foldername(name))[2])=auth.uid()::text)));
CREATE OR REPLACE FUNCTION public.guard_private_crm_file() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.bucket<>'crm-private' OR split_part(NEW.path,'/',1)<>NEW.tenant_id::text OR split_part(NEW.path,'/',2)<>NEW.uploaded_by::text OR (auth.uid() IS NOT NULL AND NEW.uploaded_by IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION 'Tài liệu CRM phải lưu trong kho riêng đúng sàn và người tải';END IF;
ELSIF NEW.bucket IS DISTINCT FROM OLD.bucket OR NEW.path IS DISTINCT FROM OLD.path OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by THEN RAISE EXCEPTION 'Không được đổi vị trí hoặc chủ tài liệu';END IF;
IF NEW.related_id IS NOT NULL AND NOT private.crm_record_read(NEW.tenant_id,NEW.related_type,NEW.related_id) AND auth.uid() IS NOT NULL AND NOT private.crm_admin(NEW.tenant_id) THEN RAISE EXCEPTION 'Không có quyền hồ sơ liên kết';END IF;RETURN NEW;END $$;
CREATE TRIGGER guard_private_crm_file BEFORE INSERT OR UPDATE ON public.files FOR EACH ROW EXECUTE FUNCTION public.guard_private_crm_file();
REVOKE ALL ON FUNCTION public.guard_crm_assignment(),public.guard_crm_tenant_refs(),public.guard_role_boundary(),public.expire_changed_ctv_invites(),public.guard_private_crm_file() FROM PUBLIC,anon,authenticated;